    source: "Facta",
    url: "https://www.facta.news/antibufale/proetesta-vigili-del-fuoco-francia-proteste-studenti",
    time: "5 giorni fa",
    pub_ts: 1791535093,
    published_at: "2026-10-09T08:38:13+00:00",
    language: "it",
    score: 1,
